/** @calc-zone presentation */
/**
 * The CSS of the theme axes (src/ui/theme/axes.css, generated by `npm run theme:gen`). Per axis value that changes tokens, two rules:
 *   [data-ac-density='compact'] { --ac-pad-card: .85rem; … }          the tokens the value sets (specificity 0,1,0; the file loads after tokens.css)
 *   :where([data-ac-density='compact']) { --ac-pad: var(--ac-…); … } the tokens built on them, declared again so that the attribute also works on a
 *                                                                   sub-tree (a live preview), not only on :root; specificity 0, so an explicit
 *                                                                   value of another axis always wins over a re-declared reference.
 */
import { THEME_DEFAULT, type TokenName } from './index';
import { AXES, AXIS_NAMES, axisAttr } from './axes';
import type { TokenSet } from './variants';

const css = (v: string): string => v.replace(/\{([a-z0-9-]+)\}/g, 'var(--ac-$1)');
const decls = (set: TokenSet): string => Object.entries(set).map(([n, v]) => `--ac-${n}: ${css(v as string)};`).join(' ');

/** Tokens of the default table whose value refers, directly or through other tokens, to one of `changed` (and are not in it). */
export function dependents(changed: readonly string[]): TokenName[] {
  const hit = new Set<string>(changed), out: TokenName[] = [];
  for (let grew = true; grew;) {
    grew = false;
    for (const [n, v] of Object.entries(THEME_DEFAULT)) {
      if (hit.has(n)) continue;
      if ([...v.matchAll(/\{([a-z0-9-]+)\}/g)].some((m) => hit.has(m[1]!))) { hit.add(n); out.push(n as TokenName); grew = true; }
    }
  }
  return out;
}

/** The whole generated block: every non-default value of every axis that changes tokens (the control axes change none). */
export function axesCss(): string {
  const out: string[] = [];
  for (const k of AXIS_NAMES) {
    for (const [value, set] of Object.entries(AXES[k].values as Record<string, TokenSet>)) {
      if (value === AXES[k].default || !Object.keys(set).length) continue;
      const sel = `[${axisAttr(k)}='${value}']`, deps = dependents(Object.keys(set));
      out.push(`/* ${AXES[k].group} · ${AXES[k].label}: ${value} */`, `${sel} { ${decls(set)} }`);
      if (deps.length) out.push(`:where(${sel}) { ${decls(Object.fromEntries(deps.map((n) => [n, THEME_DEFAULT[n]])))} }`);
    }
  }
  return out.join('\n');
}
